<script>
  import Registry from './Registry.svelte';
  import Icon from './Icon.svelte';
  import { iso, prettyDate } from './data.js';
  import { visiblePatients } from './roles.js';

  export let page;
  export let data;
  export let role;
  export let staff;
  export let onPatient = () => {};
  export let onInquiry = () => {};
  export let onNavigate = () => {};


  $: myPatients = visiblePatients(role, data.patients, staff).filter(item => item.status !== 'Archived');
  $: planRows = myPatients.flatMap(patient => (data.clinical?.[patient.id]?.carePlan?.goals || []).map(goal => ({ ...goal, patient }))).sort((a,b) => a.due.localeCompare(b.due));
  $: reportRows = myPatients.flatMap(patient => (data.clinical?.[patient.id]?.reports || []).map(report => ({ ...report, patient }))).sort((a,b) => b.createdAt.localeCompare(a.createdAt));
  $: handoffInquiries = data.inquiries.filter(item => item.owner === staff.assignment && item.stage !== 'Arrival planned');
  $: handoffConsents = data.patients.filter(patient => patient.coordinator === staff.name && patient.status !== 'Archived').flatMap(patient => (data.clinical?.[patient.id]?.consents || []).filter(item => item.status !== 'Recorded').map(item => ({ ...item, patient })));
  $: handoffFollowups = data.followups.filter(item => item.owner === staff.assignment && item.status !== 'Completed');
  $: arrivals = data.inquiries.filter(item => item.stage === 'Arrival planned' && item.deskOwner === staff.assignment).sort((a,b)=>a.date.localeCompare(b.date));
  $: readyBeds = data.rooms.filter(room => room.status === 'Ready').flatMap(room => room.beds).filter(value => !value).length;

  const pageInfo = {
    careplans: ['MY CARE PLANS', 'Care plans & reviews', 'Review goals, due dates and recorded progress across your assigned caseload.'],
    clinicalreports: ['CLINICAL REPORTS', 'Clinical reports', 'Work through drafts and finalized reports without searching patient by patient.'],
    handoffs: ['COORDINATION QUEUE', 'Handoffs & follow-through', 'Intake decisions, permissions and aftercare actions assigned to you.'],
    arrivals: ['FRONT DESK / ARRIVALS', 'Planned arrivals', 'See planned arrivals, contact details and room readiness in one desk view.']
  };
</script>

<div class="role-tasks">
  <div class="page-intro"><div><div class="eyebrow">{pageInfo[page][0]} · {staff.name}</div><h1 class="page-title">{pageInfo[page][1]}</h1><p class="page-desc">{pageInfo[page][2]}</p></div><div class="intro-actions">{#if page === 'careplans' || page === 'clinicalreports'}<button class="btn btn-outline" on:click={() => onNavigate('patients')}><Icon name="users" size={15}/> Patient directory</button>{:else if page === 'handoffs'}<button class="btn btn-outline" on:click={() => onNavigate('admissions')}><Icon name="inbox" size={15}/> Intake pipeline</button>{:else}<button class="btn btn-outline" on:click={() => onNavigate('rooms')}><Icon name="bed" size={15}/> Room board</button>{/if}</div></div>

  {#if page === 'careplans'}
    <div class="task-stats"><article><span>ASSIGNED PATIENTS</span><strong>{myPatients.length}</strong><small>Your active caseload</small></article><article><span>OPEN GOALS</span><strong>{planRows.filter(item=>item.status!=='Completed').length}</strong><small>With named owners</small></article><article><span>DUE IN 7 DAYS</span><strong>{planRows.filter(item=>item.status!=='Completed' && item.due<=iso(7)).length}</strong><small>Review dates to confirm</small></article><article><span>NEEDS REVIEW</span><strong>{planRows.filter(item=>item.status==='Needs review').length}</strong><small>Flagged in the plan</small></article></div>
    <section class="task-panel"><div class="task-panel-head"><div><span>CARE-PLAN WORKLIST</span><h2>Goals by review date</h2><p>Open a goal to see the full context, notes and linked case review.</p></div></div><Registry items={planRows} label="Care goals" pageSize={10} scope={page+staff.id} searchKeys={['title','detail','patient.name','patient.id','owner']} fields={[{key:'status',label:'Status'},{key:'patient.name',label:'Patient'},{key:'owner',label:'Owner'},{id:'due',key:item=>item.status==='Completed'?'Completed':item.due<iso(0)?'Overdue':item.due<=iso(7)?'Due within 7 days':'Later',label:'Review status'}]} dateKey="due" dateLabel="Review date" sorts={[{key:'due',label:'Review due soonest'},{key:'progress',label:'Least progress first'},{key:'patient.name',label:'Patient name'}]} let:rows><div class="task-list-cards">{#each rows as goal}<article><span class="task-date"><small>REVIEW</small><strong>{prettyDate(goal.due)}</strong></span><div class="task-card-body"><div><span class:urgent={goal.due<=iso(0)&&goal.status!=='Completed'} class="task-status">{goal.status}</span><small>{goal.patient.id} · {goal.patient.name}</small></div><h3>{goal.title}</h3><p>{goal.detail}</p><div class="task-progress"><span style:width={goal.progress+'%'}></span></div><small>{goal.progress}% recorded progress · Owner {goal.owner}</small></div><div class="task-actions"><button class="btn btn-soft btn-tiny" on:click={() => onPatient(goal.patient.id,'Care plan')}>Open plan</button><button class="text-link" on:click={() => onPatient(goal.patient.id,'AI review')}>Case review →</button></div></article>{:else}<p class="task-empty">No goals match this view.</p>{/each}</div></Registry></section>
  {:else if page === 'clinicalreports'}
    <div class="task-stats"><article><span>REPORTS IN CASELOAD</span><strong>{reportRows.length}</strong><small>Across assigned patients</small></article><article><span>DRAFTS</span><strong>{reportRows.filter(item=>item.status==='Draft').length}</strong><small>Awaiting staff review</small></article><article><span>FINALIZED</span><strong>{reportRows.filter(item=>item.status==='Final').length}</strong><small>In the patient record</small></article><article><span>CASE REVIEW DRAFTS</span><strong>{reportRows.filter(item=>item.generatedBy==='Cedar case review').length}</strong><small>Source-linked drafts</small></article></div>
    <section class="task-panel"><div class="task-panel-head"><div><span>REPORT LIBRARY</span><h2>Clinical writing queue</h2><p>Open the patient record to edit, verify sources, finalize or print.</p></div></div><Registry items={reportRows} label="Clinical reports" pageSize={25} scope={page+staff.id} searchKeys={['title','patient.name','patient.id','author','type']} fields={[{key:'status',label:'Status'},{key:'patient.name',label:'Patient'},{key:'type',label:'Report type'},{key:'author',label:'Author'}]} dateKey="createdAt" dateLabel="Created date" sorts={[{key:'createdAt',desc:true,label:'Newest first'},{key:'createdAt',label:'Oldest first'},{key:'patient.name',label:'Patient name'}]} let:rows><div class="task-report-list">{#each rows as report}<article><span class="task-report-icon"><Icon name="inbox" size={18}/></span><div><span class:final={report.status==='Final'} class="task-report-status">{report.type} · {report.status}</span><h3>{report.title}</h3><p>{report.patient.name} · {report.patient.id} · {prettyDate(report.periodStart)}–{prettyDate(report.periodEnd)} · {report.author}</p>{#if report.generatedBy}<small>Generated from a source-linked case review; staff verification required.</small>{/if}</div><button class="btn btn-soft btn-tiny" on:click={() => onPatient(report.patient.id,'Reports')}>Open report <Icon name="arrow" size={13}/></button></article>{:else}<p class="task-empty">No reports match this view.</p>{/each}</div></Registry></section>
  {:else if page === 'handoffs'}
    <div class="task-stats"><article><span>INTAKES TO MOVE</span><strong>{handoffInquiries.length}</strong><small>Assigned to {staff.shortName}</small></article><article><span>DOCUMENT GAPS</span><strong>{handoffInquiries.filter(item=>!item.documents).length}</strong><small>Before a staff decision</small></article><article><span>PERMISSIONS TO CHECK</span><strong>{handoffConsents.length}</strong><small>In coordinated records</small></article><article><span>FOLLOW-UPS OPEN</span><strong>{handoffFollowups.length}</strong><small>Assigned next contacts</small></article></div>
    <div class="task-columns"><section class="task-panel"><div class="task-panel-head"><div><span>INTAKE HANDOFFS</span><h2>People waiting on a next step</h2></div></div><Registry items={handoffInquiries} label="Intake handoffs" scope={page+staff.id} searchKeys={['id','subject','next','handoff']} fields={[{key:'stage',label:'Stage'},{key:'program',label:'Program'},{id:'documents',key:item=>item.documents?'Complete':'Missing documents',label:'Documents'}]} dateKey="date" dateLabel="Contact date" sorts={[{key:'date',label:'Earliest contact'},{key:'subject',label:'Name A–Z'}]} let:rows><div class="task-handoff-list">{#each rows as item}<article><span class="task-handoff-mark"><Icon name="inbox" size={17}/></span><div><strong>{item.subject} · {item.id}</strong><small>{item.stage} · {item.program} · {item.next}</small><p>{item.handoff}</p></div><button class="btn btn-soft btn-tiny" on:click={() => onInquiry(item.id)}>Open file</button></article>{:else}<p class="task-empty">No intake handoffs assigned.</p>{/each}</div></Registry></section><section class="task-panel"><div class="task-panel-head"><div><span>CONTINUITY</span><h2>Permissions and follow-through</h2></div></div><Registry items={[...handoffConsents.map(item=>({...item,queue:'Permission review',due:item.reviewDue})),...handoffFollowups.map(item=>({...item,queue:'Follow-up'}))]} label="Continuity tasks" pageSize={10} scope={page+staff.id} searchKeys={['label','patient.name','patient.id',item=>typeof item.patient==='string'?item.patient:'','action','status']} fields={[{key:'queue',label:'Task type'},{key:'status',label:'Status'}]} dateKey="due" dateLabel="Due date" sorts={[{key:'due',label:'Due soonest'},{key:'due',desc:true,label:'Latest due date'}]} let:rows><div class="task-handoff-list">{#each rows as item}{#if item.queue==='Permission review'}<article><span class="task-handoff-mark amber"><Icon name="shield" size={17}/></span><div><strong>{item.patient.name} · {item.label}</strong><small>{item.status} · Review {prettyDate(item.reviewDue)}</small></div><button class="text-link" on:click={() => onPatient(item.patient.id,'Consent')}>Review →</button></article>{:else}<article><span class="task-handoff-mark"><Icon name="heart" size={17}/></span><div><strong>{item.patient} · {item.action}</strong><small>Due {prettyDate(item.due)} · {item.status}</small></div><button class="text-link" on:click={() => onNavigate('aftercare')}>Open →</button></article>{/if}{/each}</div></Registry></section></div>
  {:else if page === 'arrivals'}
    <div class="task-stats"><article><span>ARRIVALS PLANNED</span><strong>{arrivals.length}</strong><small>Assigned to this desk</small></article><article><span>READY BEDS</span><strong>{readyBeds}</strong><small>Check placement with coordinator</small></article><article><span>CONTACTS TO CONFIRM</span><strong>{arrivals.filter(item=>!item.checklist?.firstContact).length}</strong><small>Before the welcome</small></article><article><span>WELCOME HANDOFFS</span><strong>{arrivals.filter(item=>!item.linkedPatient).length}</strong><small>Awaiting patient record</small></article></div>
    <div class="task-arrival-intro"><div><span>WELCOME DESK</span><h2>A good arrival is a series of small, confirmed details.</h2><p>Check the agreed contact method, planned date, room readiness and handoff note. The coordinator makes the admission decision and placement approval.</p></div><Icon name="leaf" size={80} stroke={1}/></div><section class="task-panel"><div class="task-panel-head"><div><span>ARRIVAL BOARD</span><h2>Planned welcomes</h2></div></div><Registry items={arrivals} label="Planned arrivals" scope={page+staff.id} searchKeys={['id','subject','location','handoff']} fields={[{key:'program',label:'Program'},{id:'contact',key:item=>item.checklist?.firstContact?'Confirmed':'To confirm',label:'First contact'},{id:'record',key:item=>item.linkedPatient?'Record created':'Awaiting record',label:'Patient record'}]} dateKey="date" dateLabel="Planned date" sorts={[{key:'date',label:'Soonest first'},{key:'subject',label:'Name A–Z'}]} let:rows><div class="task-arrival-grid">{#each rows as item}<article><div class="task-arrival-top"><span>{item.id}</span><strong>{prettyDate(item.date,{weekday:'short',day:'numeric',month:'long'})}</strong></div><h3>{item.subject}</h3><p>{item.program} · {item.location} · {item.preferredContact}</p><div class="task-arrival-check"><span class:done={item.checklist?.firstContact}>First contact</span><span class:done={item.checklist?.consent}>Sharing checked</span><span class:done={item.checklist?.assessment}>Assessment</span><span class:done={item.checklist?.funding}>Funding</span></div><div class="task-arrival-handoff"><small>STAFF HANDOFF</small><p>{item.handoff}</p></div><button class="btn btn-primary btn-tiny" on:click={() => onInquiry(item.id)}>Open arrival file <Icon name="arrow" size={13}/></button></article>{:else}<p class="task-empty">No planned arrivals are assigned to this desk.</p>{/each}</div></Registry></section>
  {/if}
  
</div>
